+.hero-visual {
+  display: flex;
+  justify-content: center;
+  align-items: center;
+}
+
+.hero-product-card {
+  position: relative;
+  background: var(--bg-raised);
+  border: 1px solid var(--border);
+  border-radius: var(--radius-lg);
+  padding: 2rem;
+  width: 100%;
+  max-width: 380px;
+  box-shadow: var(--shadow-lg);
+}
+
+.hero-product-card__badge-wrap {
+  display: flex;
+  gap: .5rem;
+  margin-bottom: 1.5rem;
+}
+
+.hero-product-card__img-wrap {
+  aspect-ratio: 1;
+  background: var(--bg-overlay);
+  border-radius: var(--radius-md);
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  margin-bottom: 1.5rem;
+  overflow: hidden;
+  position: relative;
+}
+
+.hero-product-card__img-placeholder {
+  width: 100%;
+  height: 100%;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+}
+
+.hero-product-card__name {
+  font-size: 1.15rem;
+  font-weight: 700;
+  margin-bottom: .3rem;
+}
+
+.hero-product-card__brand {
+  font-size: .82rem;
+  color: var(--text-muted);
+  margin-bottom: 1rem;
+  text-transform: uppercase;
+  letter-spacing: .06em;
+  font-weight: 600;
+}
+
+.hero-product-card__price-row {
+  display: flex;
+  align-items: center;
+  gap: .75rem;
+}
+
+.price-current {
+  font-size: 1.35rem;
+  font-weight: 800;
+  color: var(--text-primary);
+}
+
+.price-original {
+  font-size: .9rem;
+  color: var(--text-muted);
+  text-decoration: line-through;
+}
+
+.price-save {
+  font-size: .78rem;
+  font-weight: 700;
+  color: var(--danger);
+}
+
+@media (max-width: 768px) {
+  .hero-grid {
+    grid-template-columns: 1fr;
+    padding-block: 3rem;
+    text-align: center;
+  }
+  .hero-eyebrow { justify-content: center; }
+  .hero__desc { margin-inline: auto; }
+  .hero__actions { justify-content: center; }
+  .hero__stats { justify-content: center; }
+  .hero-visual { margin-top: 1.5rem; }
+}
+
+/* ============================================================
+   Product cards & grid
+   ============================================================ */
+.product-grid {
+  display: grid;
+  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
+  gap: 1.5rem;
+}
+
+.product-card {
+  background: var(--bg-surface);
+  border: 1px solid var(--border);
+  border-radius: var(--radius-md);
+  overflow: hidden;
+  transition: border-color var(--transition), box-shadow var(--transition), transform var(--transition);
+  display: flex;
+  flex-direction: column;
+}
+
+.product-card:hover {
+  border-color: var(--bg-overlay);
+  box-shadow: var(--shadow-md);
+  transform: translateY(-3px);
+}
+
+.product-card__img-wrap {
+  position: relative;
+  aspect-ratio: 1;
+  background: var(--bg-raised);
+  overflow: hidden;
+  flex-shrink: 0;
+}
+
+.product-card__img-placeholder {
+  width: 100%;
+  height: 100%;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  color: var(--text-muted);
+  font-size: 3rem;
+  transition: transform var(--transition);
+}
+.product-card:hover .product-card__img-placeholder { transform: scale(1.05); }
+
+.product-card__badges {
+  position: absolute;
+  top: .75rem;
+  left: .75rem;
+  display: flex;
+  flex-direction: column;
+  gap: .35rem;
+}
+
+.product-card__wishlist {
+  position: absolute;
+  top: .75rem;
+  right: .75rem;
+  padding: .4rem;
+  border-radius: var(--radius-pill);
+  background: rgba(13,13,15,.7);
+  border: 1.5px solid var(--border);
+  color: var(--text-muted);
+  backdrop-filter: blur(8px);
+  transition: color var(--transition), background var(--transition), border-color var(--transition);
+  line-height: 0;
+}
+.product-card__wishlist:hover { color: #e05252; border-color: rgba(224,82,82,.4); background: rgba(224,82,82,.08); }
+.product-card__wishlist:focus-visible {
+  outline: 2px solid var(--border-focus);
+  outline-offset: 2px;
+}
+.product-card__wishlist[aria-pressed="true"] { color: #e05252; border-color: rgba(224,82,82,.5); }
+
+.product-card__body {
+  padding: 1rem 1rem 1.25rem;
+  display: flex;
+  flex-direction: column;
+  flex: 1;
+}
+
+.product-card__category {
+  font-size: .72rem;
+  font-weight: 700;
+  letter-spacing: .07em;
+  text-transform: uppercase;
+  color: var(--text-muted);
+  margin-bottom: .35rem;
+}
+
+.product-card__name {
+  font-size: .95rem;
+  font-weight: 600;
+  color: var(--text-primary);
+  margin-bottom: .6rem;
+  line-height: 1.4;
+  flex: 1;
+}
+
+.product-card__stars {
+  display: flex;
+  align-items: center;
+  gap: .3rem;
+  margin-bottom: .75rem;
+}
+
+.stars { display: flex; gap: 1px; color: var(--gold); font-size: .8rem; }
+.review-count { font-size: .75rem; color: var(--text-muted); }
+
+.product-card__price-row {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: .5rem;
+  margin-bottom: .85rem;
+}
+
+.product-card__prices {
+  display: flex;
+  align-items: baseline;
+  gap: .45rem;
+  flex-wrap: wrap;
+}
+
+.product-card__add {
+  padding: .5rem 1rem;
+  font-size: .82rem;
+  border-radius: var(--radius-pill);
+  background: var(--accent);
+  color: #fff;
+  font-weight: 600;
+  transition: background var(--transition), transform var(--transition);
+  white-space: nowrap;
+}
+.product-card__add:hover { background: var(--accent-hover); }
+.product-card__add:active { transform: scale(.96); background: var(--accent-active); }
+.product-card__add:focus-visible {
+  outline: 2px solid var(--border-focus);
+  outline-offset: 3px;
+}
+
+/* ============================================================
+   Deals section
+   ============================================================ */
+.deals-grid {
+  display: grid;
+  grid-template-columns: 1.8fr 1fr;
+  gap: 1.5rem;
+}
+
+.deal-card {
+  border-radius: var(--radius-lg);
+  overflow: hidden;
+  position: relative;
+  display: flex;
+  flex-direction: column;
+  justify-content: flex-end;
+  padding: 2rem;
+  min-height: 340px;
+  background: var(--bg-raised);
+  border: 1px solid var(--border);
+}
+
+.deal-card--main {
+  background:
+    radial-gradient(ellipse 80% 70% at 100% 0%, rgba(124,106,247,.35) 0%, transparent 60%),
+    var(--bg-raised);
+}
+
+.deal-card--secondary {
+  background:
+    radial-gradient(ellipse 80% 70% at 0% 100%, rgba(245,200,66,.2) 0%, transparent 60%),
+    var(--bg-raised);
+}
+
+.deal-card__decoration {
+  position: absolute;
+  inset: 0;
+  pointer-events: none;
+  overflow: hidden;
+}
+
+.deal-card__circle {
+  position: absolute;
+  border-radius: 50%;
+  border: 1px solid rgba(255,255,255,.05);
+}
+
+.deal-card__content { position: relative; z-index: 1; }
+
+.deal-card__timer {
+  display: flex;
+  align-items: center;
+  gap: .4rem;
+  font-size: .78rem;
+  font-weight: 600;
+  color: var(--gold);
+  margin-bottom: 1rem;
+  text-transform: uppercase;
+  letter-spacing: .06em;
+}
+
+.deal-card__countdown {
+  display: flex;
+  gap: .4rem;
+  margin-bottom: 1.25rem;
+}
+
+.countdown-unit {
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  background: rgba(0,0,0,.35);
+  border: 1px solid var(--border);
+  border-radius: var(--radius-sm);
+  padding: .35rem .6rem;
+  min-width: 44px;
+}
+
+.countdown-num {
+  font-size: 1.15rem;
+  font-weight: 800;
+  letter-spacing: -.02em;
+  line-height: 1.2;
+  font-variant-numeric: tabular-nums;
+  color: var(--text-primary);
+}
+
+.countdown-label {
+  font-size: .6rem;
+  font-weight: 600;
+  letter-spacing: .06em;
+  text-transform: uppercase;
+  color: var(--text-muted);
+}
+
+.deal-card__title {
+  font-size: 1.5rem;
+  font-weight: 800;
+  line-height: 1.2;
+  margin-bottom: .5rem;
+  letter-spacing: -.02em;
+}
+
+.deal-card--main .deal-card__title { font-size: 1.9rem; }
+
+.deal-card__subtitle {
+  font-size: .9rem;
+  color: var(--text-secondary);
+  margin-bottom: 1.5rem;
+}
+
+.deal-card__off {
+  font-size: 3rem;
+  font-weight: 900;
+  background: linear-gradient(135deg, var(--gold) 0%, #ff9d42 100%);
+  -webkit-background-clip: text;
+  -webkit-text-fill-color: transparent;
+  background-clip: text;
+  line-height: 1;
+  margin-bottom: .25rem;
+  letter-spacing: -.04em;
+}
+
+.deal-card__visual {
+  position: absolute;
+  top: 1.5rem;
+  right: 1.5rem;
+  font-size: 5rem;
+  opacity: .12;
+  pointer-events: none;
+  user-select: none;
+}
+
+.deal-card--main .deal-card__visual { font-size: 8rem; top: 50%; transform: translateY(-50%); opacity: .08; }
+
+@media (max-width: 768px) {
+  .deals-grid { grid-template-columns: 1fr; }
+  .deal-card--main .deal-card__title { font-size: 1.5rem; }
+}
+
+/* ============================================================
+   Editorial cards
+   ============================================================ */
+.editorial-grid {
+  display: grid;
+  grid-template-columns: 2fr 1fr 1fr;
+  gap: 1.5rem;
+}
+
+.editorial-card {
+  border-radius: var(--radius-md);
+  overflow: hidden;
+  background: var(--bg-surface);
+  border: 1px solid var(--border);
+  display: flex;
+  flex-direction: column;
+  transition: border-color var(--transition), box-shadow var(--transition), transform var(--transition);
+}
+
+.editorial-card:hover {
+  border-color: var(--bg-overlay);
+  box-shadow: var(--shadow-md);
+  transform: translateY(-2px);
+}
+
+.editorial-card__img {
+  aspect-ratio: 16/9;
+  background: var(--bg-raised);
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  font-size: 4rem;
+  flex-shrink: 0;
+  overflow: hidden;
+  position: relative;
+}
+
+.editorial-card--featured .editorial-card__img { aspect-ratio: 16/10; font-size: 6rem; }
+
+.editorial-card__img-bg {
+  position: absolute;
+  inset: 0;
+  opacity: .35;
+}
+
+.editorial-card__img-icon { position: relative; z-index: 1; }
+
+.editorial-card__body {
+  padding: 1.25rem;
+  display: flex;
+  flex-direction: column;
+  flex: 1;
+}
+
+.editorial-card__meta {
+  display: flex;
+  align-items: center;
+  gap: .5rem;
+  margin-bottom: .75rem;
+}
+
+.editorial-card__date {
+  font-size: .72rem;
+  color: var(--text-muted);
+  font-weight: 500;
+}
+
+.editorial-card__title {
+  font-size: 1rem;
+  font-weight: 700;
+  line-height: 1.35;
+  margin-bottom: .6rem;
+  color: var(--text-primary);
+  flex: 1;
+}
+
+.editorial-card--featured .editorial-card__title { font-size: 1.3rem; }
+
+.editorial-card__excerpt {
+  font-size: .85rem;
+  color: var(--text-secondary);
+  line-height: 1.6;
+  margin-bottom: 1rem;
+  display: -webkit-box;
+  -webkit-line-clamp: 3;
+  -webkit-box-orient: vertical;
+  overflow: hidden;
+}
+
+.editorial-card__read-more {
+  font-size: .82rem;
+  font-weight: 600;
+  color: var(--accent);
+  display: inline-flex;
+  align-items: center;
+  gap: .25rem;
+  margin-top: auto;
+  transition: color var(--transition), gap var(--transition);
+}
+.editorial-card__read-more:hover { color: var(--accent-hover); gap: .5rem; }
+.editorial-card:focus-within .editorial-card__read-more { color: var(--accent-hover); }
+.editorial-card__link:focus-visible {
+  outline: 2px solid var(--border-focus);
+  outline-offset: 3px;
+  border-radius: var(--radius-sm);
+}
+
+@media (max-width: 900px) {
+  .editorial-grid { grid-template-columns: 1fr 1fr; }
+  .editorial-card--featured { grid-column: 1 / -1; }
+}
+
+@media (max-width: 600px) {
+  .editorial-grid { grid-template-columns: 1fr; }
+  .editorial-card--featured { grid-column: unset; }
+}
+
+/* ============================================================
+   Categories strip
+   ============================================================ */
+.categories-strip {
+  display: flex;
+  gap: 1rem;
+  overflow-x: auto;
+  padding-bottom: .5rem;
+  scrollbar-width: thin;
+  scrollbar-color: var(--border) transparent;
+}
+
+.category-pill {
+  flex-shrink: 0;
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  gap: .6rem;
+  padding: 1.1rem 1.4rem;
+  background: var(--bg-surface);
+  border: 1.5px solid var(--border);
+  border-radius: var(--radius-md);
+  transition: border-color var(--transition), background var(--transition), transform var(--transition);
+  cursor: pointer;
+  color: var(--text-primary);
+}
+
+.category-pill:hover,
+.category-pill[aria-pressed="true"] {
+  border-color: var(--accent);
+  background: rgba(124,106,247,.08);
+  transform: translateY(-2px);
+}
+
+.category-pill:focus-visible {
+  outline: 2px solid var(--border-focus);
+  outline-offset: 3px;
+  border-radius: var(--radius-md);
+}
+
+.category-pill__icon {
+  font-size: 1.6rem;
+  line-height: 1;
+}
+
+.category-pill__label {
+  font-size: .78rem;
+  font-weight: 600;
+  color: var(--text-secondary);
+  white-space: nowrap;
+}
+
+.category-pill:hover .category-pill__label,
+.category-pill[aria-pressed="true"] .category-pill__label {
+  color: var(--accent-hover);
+}
+
+/* ============================================================
+   Promo banner
+   ============================================================ */
+.promo-banner {
+  background: linear-gradient(135deg, rgba(124,106,247,.15) 0%, rgba(245,200,66,.08) 100%);
+  border: 1px solid rgba(124,106,247,.3);
+  border-radius: var(--radius-lg);
+  padding: 2.5rem 3rem;
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 2rem;
+  flex-wrap: wrap;
+}
+
+.promo-banner__text { flex: 1; }
+.promo-banner__eyebrow {
+  font-size: .75rem;
+  font-weight: 700;
+  letter-spacing: .1em;
+  text-transform: uppercase;
+  color: var(--accent);
+  margin-bottom: .5rem;
+}
+.promo-banner__title {
+  font-size: clamp(1.25rem, 3vw, 1.7rem);
+  font-weight: 800;
+  letter-spacing: -.02em;
+  margin-bottom: .4rem;
+}
+.promo-banner__sub {
+  font-size: .9rem;
+  color: var(--text-secondary);
+}
+.promo-banner__actions {
+  display: flex;
+  gap: .75rem;
+  flex-wrap: wrap;
+  align-items: center;
+  flex-shrink: 0;
+}
+
+/* ============================================================
+   Newsletter
+   ============================================================ */
+.newsletter {
+  text-align: center;
+  max-width: 520px;
+  margin-inline: auto;
+}
+
+.newsletter__title {
+  font-size: clamp(1.4rem, 3vw, 1.9rem);
+  font-weight: 800;
+  letter-spacing: -.03em;
+  margin-bottom: .75rem;
+}
+
+.newsletter__desc {
+  color: var(--text-secondary);
+  font-size: .95rem;
+  margin-bottom: 1.75rem;
+}
+
+.newsletter__form {
+  display: flex;
+  gap: .5rem;
+  max-width: 420px;
+  margin-inline: auto;
+}
+
+.newsletter__input {
+  flex: 1;
+  padding: .7rem 1rem;
+  background: var(--bg-raised);
+  border: 1.5px solid var(--border);
+  border-radius: var(--radius-pill);
+  color: var(--text-primary);
+  font-size: .9rem;
+  font-family: inherit;
+  transition: border-color var(--transition), box-shadow var(--transition);
+  min-width: 0;
+}
+.newsletter__input::placeholder { color: var(--text-muted); }
+.newsletter__input:focus {
+  outline: none;
+  border-color: var(--border-focus);
+  box-shadow: 0 0 0 3px rgba(124,106,247,.18);
+}
+
+.newsletter__form:has(.newsletter__input:focus) .btn--primary {
+  box-shadow: 0 0 0 3px rgba(124,106,247,.18);
+}
+
+.newsletter__privacy {
+  font-size: .75rem;
+  color: var(--text-muted);
+  margin-top: .9rem;
+}
+
+@media (max-width: 480px) {
+  .newsletter__form { flex-direction: column; }
+}
+
+/* ============================================================
+   Footer
+   ============================================================ */
+.site-footer {
+  background: var(--bg-surface);
+  border-top: 1px solid var(--border);
+  padding-top: 4rem;
+  padding-bottom: 2rem;
+}
+
+.footer-grid {
+  display: grid;
+  grid-template-columns: 1.5fr repeat(3, 1fr);
+  gap: 3rem;
+  margin-bottom: 3rem;
+}
+
+.footer-brand__desc {
+  font-size: .875rem;
+  color: var(--text-secondary);
+  margin-top: .9rem;
+  margin-bottom: 1.25rem;
+  line-height: 1.65;
+  max-width: 26ch;
+}
+
+.footer-social {
+  display: flex;
+  gap: .5rem;
+}
+
+.social-btn {
+  width: 36px;
+  height: 36px;
+  border-radius: var(--radius-sm);
+  background: var(--bg-raised);
+  border: 1.5px solid var(--border);
+  display: grid;
+  place-items: center;
+  color: var(--text-muted);
+  font-size: .8rem;
+  transition: color var(--transition), border-color var(--transition), background var(--transition);
+}
+.social-btn:hover { color: var(--text-primary); border-color: var(--text-muted); background: var(--bg-overlay); }
+.social-btn:focus-visible {
+  outline: 2px solid var(--border-focus);
+  outline-offset: 3px;
+  border-radius: var(--radius-sm);
+}
+
+.footer-col__title {
+  font-size: .78rem;
+  font-weight: 700;
+  letter-spacing: .08em;
+  text-transform: uppercase;
+  color: var(--text-muted);
+  margin-bottom: 1rem;
+}
+
+.footer-col__links { display: flex; flex-direction: column; gap: .5rem; }
+
+.footer-col__link {
+  font-size: .875rem;
+  color: var(--text-secondary);
+  transition: color var(--transition);
+  width: fit-content;
+}
+.footer-col__link:hover { color: var(--text-primary); }
+.footer-col__link:focus-visible {
+  outline: 2px solid var(--border-focus);
+  outline-offset: 3px;
+  border-radius: 2px;
+}
+
+.footer-bottom {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  flex-wrap: wrap;
+  gap: 1rem;
+  padding-top: 2rem;
+  border-top: 1px solid var(--border);
+  font-size: .8rem;
+  color: var(--text-muted);
+}
+
+.footer-bottom__legal { display: flex; gap: 1.25rem; flex-wrap: wrap; }
+.footer-bottom__legal a {
+  color: var(--text-muted);
+  transition: color var(--transition);
+}
+.footer-bottom__legal a:hover { color: var(--text-secondary); }
+.footer-bottom__legal a:focus-visible {
+  outline: 2px solid var(--border-focus);
+  outline-offset: 3px;
+  border-radius: 2px;
+}
+
+@media (max-width: 900px) {
+  .footer-grid { grid-template-columns: 1fr 1fr; }
+}
+@media (max-width: 560px) {
+  .footer-grid { grid-template-columns: 1fr; }
+}
+
+/* ============================================================
+   Notification toast
+   ============================================================ */
+#toast-region {
+  position: fixed;
+  bottom: 1.5rem;
+  right: 1.5rem;
+  display: flex;
+  flex-direction: column;
+  gap: .5rem;
+  z-index: 500;
+  pointer-events: none;
+}
+
+.toast {
+  background: var(--bg-raised);
+  border: 1px solid var(--border);
+  border-radius: var(--radius-md);
+  padding: .85rem 1.2rem;
+  font-size: .875rem;
+  color: var(--text-primary);
+  box-shadow: var(--shadow-md);
+  pointer-events: auto;
+  display: flex;
+  align-items: center;
+  gap: .6rem;
+  max-width: 320px;
+  animation: toast-in .25s ease forwards;
+  border-left: 3px solid var(--accent);
+}
+
+.toast.toast--out { animation: toast-out .25s ease forwards; }
+
+.toast__icon { flex-shrink: 0; color: var(--accent); }
+
+@keyframes toast-in {
+  from { opacity: 0; transform: translateY(8px) scale(.97); }
+  to   { opacity: 1; transform: translateY(0) scale(1); }
+}
+@keyframes toast-out {
+  from { opacity: 1; transform: translateY(0) scale(1); }
+  to   { opacity: 0; transform: translateY(8px) scale(.97); }
+}
+
+/* ============================================================
+   Forced colors
