  { label: "Cameras",     icon: "📷", id: "cameras" },
];

/* ---------- State ---------- */
const state = {
  cartCount: 3,
  wishlist: new Set([3]),
  activeCategory: "all",
  countdownEnd: Date.now() + (7 * 60 + 42) * 60_000 + 19 * 1_000,
};

/* ---------- DOM helpers ---------- */
const qs  = (sel, root = document) => root.querySelector(sel);
const qsa = (sel, root = document) => [...root.querySelectorAll(sel)];

function h(tag, attrs = {}, ...children) {
  const el = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs)) {
    if (k.startsWith("on") && typeof v === "function") {
      el.addEventListener(k.slice(2).toLowerCase(), v);
    } else if (k === "className") {
      el.className = v;
    } else if (k === "innerHTML") {
      el.innerHTML = v;
    } else {
      el.setAttribute(k, v);
    }
  }
  for (const child of children.flat()) {
    if (child == null) continue;
    el.append(typeof child === "string" ? document.createTextNode(child) : child);
  }
  return el;
}

/* ---------- Toast ---------- */
function showToast(message, icon = "✓") {
  const region = qs("#toast-region");
  const toast = h("div", { className: "toast", role: "status" },
    h("span", { className: "toast__icon", "aria-hidden": "true" }, icon),
    message,
  );
  region.appendChild(toast);
  setTimeout(() => {
    toast.classList.add("toast--out");
    toast.addEventListener("animationend", () => toast.remove(), { once: true });
  }, 3000);
}

/* ---------- Cart ---------- */
function updateCartCount(delta) {
  state.cartCount = Math.max(0, state.cartCount + delta);
  const badge = qs(".cart-count");
  if (badge) {
    badge.textContent = state.cartCount;
    badge.setAttribute("aria-label", `Cart, ${state.cartCount} item${state.cartCount !== 1 ? "s" : ""}`);
  }
}

/* ---------- Stars ---------- */
function renderStars(rating) {
  const full  = Math.floor(rating);
  const half  = rating % 1 >= 0.5 ? 1 : 0;
  const empty = 5 - full - half;
  return "★".repeat(full) + (half ? "½" : "") + "☆".repeat(empty);
}

/* ---------- Product card ---------- */
function ProductCard(product) {
  const inWishlist = state.wishlist.has(product.id);
  const discount = product.originalPrice
    ? Math.round((1 - product.price / product.originalPrice) * 100)
    : null;

  const card = h("article", { className: "product-card" },
    /* Image area */
    h("div", { className: "product-card__img-wrap" },
      h("div", {
        className: "product-card__img-placeholder",
        role: "img",
        "aria-label": product.name,
      }, product.icon),
      product.badge
        ? h("div", { className: "product-card__badges" },
            h("span", { className: `badge badge--${product.badgeType}` }, product.badge),
          )
        : null,
      discount
        ? h("div", { className: "product-card__badges", style: product.badge ? "top:2.5rem" : "" },
            h("span", { className: "badge badge--danger" }, `-${discount}%`),
          )
        : null,
      /* Wishlist */
      h("button", {
        className: "product-card__wishlist",
        "aria-pressed": String(inWishlist),
        "aria-label": `${inWishlist ? "Remove from" : "Add to"} wishlist: ${product.name}`,
        onClick(e) {
          const btn = e.currentTarget;
          const active = state.wishlist.has(product.id);
          if (active) {
            state.wishlist.delete(product.id);
            btn.setAttribute("aria-pressed", "false");
            btn.setAttribute("aria-label", `Add to wishlist: ${product.name}`);
            btn.innerHTML = heartSVG(false);
            showToast("Removed from wishlist", "♡");
          } else {
            state.wishlist.add(product.id);
            btn.setAttribute("aria-pressed", "true");
            btn.setAttribute("aria-label", `Remove from wishlist: ${product.name}`);
            btn.innerHTML = heartSVG(true);
            showToast("Added to wishlist", "♥");
          }
        },
      }, ...[]),
    ),
    /* Body */
    h("div", { className: "product-card__body" },
      h("p", { className: "product-card__category" }, product.category),
      h("h3", { className: "product-card__name" }, product.name),
      h("div", { className: "product-card__stars" },
        h("span", { className: "stars", "aria-hidden": "true" }, renderStars(product.rating)),
        h("span", { className: "review-count" }, `(${product.reviews.toLocaleString()})`),
        h("span", { className: "sr-only" }, `Rated ${product.rating} out of 5, ${product.reviews.toLocaleString()} reviews`),
      ),
      h("div", { className: "product-card__price-row" },
        h("div", { className: "product-card__prices" },
          h("span", { className: "price-current" }, `$${product.price}`),
          product.originalPrice
            ? h("span", { className: "price-original" }, `$${product.originalPrice}`)
            : null,
        ),
        h("button", {
          className: "product-card__add",
          "aria-label": `Add ${product.name} to cart`,
          onClick() {
            updateCartCount(1);
            showToast(`Added to cart`, "🛒");
          },
        }, "Add to cart"),
      ),
    ),
  );

  /* Set initial wishlist icon */
  const wishBtn = qs(".product-card__wishlist", card);
  wishBtn.innerHTML = heartSVG(inWishlist);
  return card;
}

function heartSVG(filled) {
  return filled
    ? `<svg width="16" height="16" viewBox="0 0 24 24" fill="#e05252" aria-hidden="true"><path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z"/></svg>`
    : `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"/></svg>`;
}

/* ---------- Editorial card ---------- */
function EditorialCard(article) {
  const card = h("article", { className: `editorial-card${article.featured ? " editorial-card--featured" : ""}` },
    h("div", { className: "editorial-card__img" },
      h("div", { className: "editorial-card__img-bg", style: `background:${article.gradient}`, "aria-hidden": "true" }),
      h("span", { className: "editorial-card__img-icon", "aria-hidden": "true" }, article.icon),
    ),
    h("div", { className: "editorial-card__body" },
      h("div", { className: "editorial-card__meta" },
        h("span", { className: `badge badge--${article.tagType}` }, article.tag),
        h("span", { className: "editorial-card__date" }, article.date),
      ),
      h("h3", { className: "editorial-card__title" }, article.title),
      article.featured
        ? h("p", { className: "editorial-card__excerpt" }, article.excerpt)
        : null,
      h("a", {
        href: "#",
        className: "editorial-card__link editorial-card__read-more",
        "aria-label": `Read more: ${article.title}`,
        onClick(e) { e.preventDefault(); },
      }, "Read article ", h("span", { "aria-hidden": "true" }, "→")),
    ),
  );
  return card;
}

/* ---------- Countdown ---------- */
function updateCountdown() {
  const remaining = Math.max(0, state.countdownEnd - Date.now());
  const h = Math.floor(remaining / 3_600_000);
  const m = Math.floor((remaining % 3_600_000) / 60_000);
  const s = Math.floor((remaining % 60_000) / 1_000);

  const pad = n => String(n).padStart(2, "0");

  const hEl = qs(".countdown-h");
  const mEl = qs(".countdown-m");
  const sEl = qs(".countdown-s");
  if (hEl) hEl.textContent = pad(h);
  if (mEl) mEl.textContent = pad(m);
  if (sEl) sEl.textContent = pad(s);

  /* Update live region accessible text */
  const liveEl = qs(".countdown-live");
  if (liveEl && s % 10 === 0) {
    liveEl.textContent = `${pad(h)} hours, ${pad(m)} minutes, ${pad(s)} seconds remaining`;
  }
}

/* ---------- Category filter ---------- */
function filterProducts(categoryId) {
  state.activeCategory = categoryId;

  /* Update button states */
  qsa(".category-pill").forEach(btn => {
    const active = btn.dataset.category === categoryId;
    btn.setAttribute("aria-pressed", String(active));
  });

  /* Re-render product grid */
  const grid = qs("#product-grid");
  if (!grid) return;
  grid.innerHTML = "";
  const products = categoryId === "all"
    ? PRODUCTS
    : PRODUCTS.filter(p => p.category.toLowerCase() === categoryId);
  products.forEach(p => grid.appendChild(ProductCard(p)));
}

/* ---------- Mobile nav ---------- */
function initMobileNav() {
  const toggle = qs(".mobile-menu-toggle");
  const nav    = qs(".mobile-nav");
  if (!toggle || !nav) return;

  toggle.addEventListener("click", () => {
    const open = nav.classList.toggle("is-open");
    toggle.setAttribute("aria-expanded", String(open));
    toggle.setAttribute("aria-label", open ? "Close navigation menu" : "Open navigation menu");
  });

  /* Close on Escape */
  document.addEventListener("keydown", e => {
    if (e.key === "Escape" && nav.classList.contains("is-open")) {
      nav.classList.remove("is-open");
      toggle.setAttribute("aria-expanded", "false");
      toggle.setAttribute("aria-label", "Open navigation menu");
      toggle.focus();
    }
  });
}

/* ---------- Newsletter form ---------- */
function initNewsletter() {
  const form = qs(".newsletter__form");
  if (!form) return;
  form.addEventListener("submit", e => {
    e.preventDefault();
    const input = qs(".newsletter__input", form);
    if (!input.value.trim()) return;
    showToast("You're subscribed! Welcome to NOVA.", "✉️");
    input.value = "";
  });
}

/* ---------- Hero add-to-cart ---------- */
function initHeroCart() {
  const btn = qs(".hero-add-cart");
  if (!btn) return;
  btn.addEventListener("click", () => {
    updateCartCount(1);
    showToast("Added to cart", "🛒");
  });
}

/* ---------- Bootstrap ---------- */
document.addEventListener("DOMContentLoaded", () => {
  /* Render product grid */
  const grid = qs("#product-grid");
  PRODUCTS.forEach(p => grid.appendChild(ProductCard(p)));

  /* Render editorial grid */
  const editGrid = qs("#editorial-grid");
  EDITORIAL.forEach(a => editGrid.appendChild(EditorialCard(a)));

  /* Category pills */
  const catStrip = qs("#categories-strip");
  CATEGORIES.forEach(cat => {
    const pill = h("button", {
      className: "category-pill",
      "data-category": cat.id,
      "aria-pressed": cat.id === "all" ? "true" : "false",
      onClick() { filterProducts(cat.id); },
    },
      h("span", { className: "category-pill__icon", "aria-hidden": "true" }, cat.icon),
      h("span", { className: "category-pill__label" }, cat.label),
    );
    catStrip.appendChild(pill);
  });

  /* Countdown */
  updateCountdown();
  setInterval(updateCountdown, 1000);

  initMobileNav();
  initNewsletter();
  initHeroCart();
});
