      el.addEventListener(k.slice(2).toLowerCase(), v);
    } else if (k === "className") {
      el.className = v;
    } else if (k === "innerHTML") {
      el.innerHTML = v;
    } else {
      el.setAttribute(k, v);
    }
  }
  for (const child of children.flat()) {
    if (child == null) continue;
    el.append(typeof child === "string" ? document.createTextNode(child) : child);
  }
  return el;
}

